<?php require 'config/database.php';require 'config/app.php';if(!isset($_SESSION['player_id'])){flash('warning','Log in to see your dashboard.');go('login.php');}$s=$pdo->prepare("SELECT r.*,t.name AS tournament_name,t.tournament_date,p.status AS payment_status,p.amount FROM registrations r JOIN tournaments t ON t.tournament_id=r.tournament_id LEFT JOIN payments p ON p.registration_id=r.registration_id WHERE r.player_id=? ORDER BY r.created_at DESC");$s->execute([(int)$_SESSION['player_id']]);$rows=$s->fetchAll();$pageTitle='My Arena';require 'includes/header.php';?>
<section class="page-hero"><div class="eyebrow">PLAYER CONTROL ROOM</div><h1>WELCOME BACK, <span><?=e(strtoupper(explode(' ',$_SESSION['player_name']??'PLAYER')[0]))?>.</span></h1><p>Everything your squad needs, all in one place.</p><a class="btn btn-hot" href="tournaments.php">Find a tournament ↗</a></section><section class="section box"><div class="section-head"><div><div class="eyebrow">YOUR COMPETITION HISTORY</div><h2>MY <span>ENTRIES.</span></h2></div></div><?php if($rows):?><div class="table-responsive"><table class="table arena-table"><thead><tr><th>TOURNAMENT / TEAM</th><th>DATE</th><th>ENTRY STATUS</th><th>PAYMENT</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['tournament_name'])?></b><small><?=e($r['team_name'])?> · <?=e($r['registration_code'])?></small></td><td><?=e(date('d M Y',strtotime($r['tournament_date'])))?></td><td><span class="chip"><?=e(str_replace('_',' ',$r['status']))?></span></td><td><span class="chip"><?=e(str_replace('_',' ',$r['payment_status']??'unpaid'))?></span></td><td><a class="text-link" href="entry.php?id=<?=(int)$r['registration_id']?>">View ↗</a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty"><h3>Your story starts with one entry.</h3><p>You haven't registered for a tournament yet.</p><a href="tournaments.php" class="btn btn-hot">Explore tournaments</a></div><?php endif;?></section><?php require 'includes/footer.php';?>
